// Normalization & Telemetry Extraction Engine
const body = $input.first().json.body || $input.first().json;

const cleanCompany = (body.company || 'Unknown Prime / OEM').trim();
const cleanName = (body.name || 'Anonymous Estimator').trim();
const cleanEmail = (body.email || '').trim().toLowerCase();
const cleanPhone = (body.phone || '').trim();
const projectCity = (body.projectLocation || body.city || 'Intermountain West').trim();
const sourcePage = (body.source || 'Panel Builder Configurator').trim();

const config = body.configuration || {};
const enclosure = config.enclosure || 'NEMA 4X (316L)';
const voltage = config.voltage || '480V 3-Phase';
const sccr = config.sccr || '65kA Coordinated';
const plc = config.controller || 'Rockwell CompactLogix 5380';
const dimensions = config.dimensions || '60"H x 36"W x 14"D';
const thermalWatts = config.totalWatts || '620W';
const cooling = config.cooling || 'Closed-Loop NEMA 4X AC';
const budgetRange = config.budgetRange || '$18,500 - $24,200';
const leadTime = config.leadTime || '8-10 Weeks';

const alertMessage = `⚡ NEW INDUSTRIAL CONTROL PANEL RFQ\n\n` +
  `• Company: ${cleanCompany}\n` +
  `• Contact: ${cleanName} (${cleanEmail} / ${cleanPhone})\n` +
  `• Location: ${projectCity}\n` +
  `• Budget Range: ${budgetRange}\n` +
  `• Lead Time SLA: ${leadTime}\n` +
  `• Enclosure: ${enclosure} (${dimensions})\n` +
  `• Voltage & SCCR: ${voltage} | ${sccr}\n` +
  `• Control Core: ${plc}\n` +
  `• Thermal Load: ${thermalWatts} (${cooling})\n` +
  `• Source: ${sourcePage}`; 

return [{
  json: {
    cleanCompany,
    cleanName,
    cleanEmail,
    cleanPhone,
    projectCity,
    sourcePage,
    enclosure,
    voltage,
    sccr,
    plc,
    dimensions,
    thermalWatts,
    cooling,
    budgetRange,
    leadTime,
    alertMessage,
    timestamp: new Date().toISOString()
  }
}];
